package com.medtrack.supplier.service; import com.medtrack.shared.exception.*; import com.medtrack.supplier.dto.*; import com.medtrack.supplier.entity.Supplier; import com.medtrack.supplier.repository.SupplierRepository; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class SupplierService {private final SupplierRepository repo; public SupplierService(SupplierRepository r){repo=r;} public SupplierResponse create(SupplierRequest r){if(repo.existsByCode(r.code()))throw new DomainException("DUPLICATE_SUPPLIER_CODE","Supplier code already exists");return SupplierResponse.of(repo.save(new Supplier(r.name(),r.code(),r.contactEmail(),r.contactPhone(),r.address())));} @Transactional(readOnly=true) public Page<SupplierResponse> list(Pageable p){return repo.findAll(p).map(SupplierResponse::of);} @Transactional(readOnly=true) public SupplierResponse get(UUID id){return SupplierResponse.of(find(id));} public SupplierResponse update(UUID id,SupplierRequest r){Supplier s=find(id);s.update(r.name(),r.contactEmail(),r.contactPhone(),r.address());return SupplierResponse.of(s);} private Supplier find(UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Supplier"));}}
